import{_ as o,o as e,c as d,a2 as l}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（不设分类小节、变更条目置顶、单条 ≤120 字、同源优先合并、只留 API 锚点不写症状白描、不写实现细节与常量数值、禁「优化并更新 X 组件」与「… 组件」后缀、引用的组件与属性须核实）。撰写、修订或回改历史条目时加载。","frontmatter":{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（不设分类小节、变更条目置顶、单条 ≤120 字、同源优先合并、只留 API 锚点不写症状白描、不写实现细节与常量数值、禁「优化并更新 X 组件」与「… 组件」后缀、引用的组件与属性须核实）。撰写、修订或回改历史条目时加载。"},"headers":[],"relativePath":"rules/按需-更新日志编写规范.md","filePath":"rules/按需-更新日志编写规范.md","lastUpdated":null}'),r={name:"rules/按需-更新日志编写规范.md"};function i(c,t,s,a,n,g){return e(),d("div",null,[...t[0]||(t[0]=[l('<blockquote><p>📄 本页由源文件 <code>rules/按需-更新日志编写规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-更新日志编写规范" tabindex="-1">按需-更新日志编写规范 <a class="header-anchor" href="#按需-更新日志编写规范" aria-label="Permalink to &quot;按需-更新日志编写规范&quot;">​</a></h1><blockquote><p>触发时机：撰写或修订项目 <code>changelog.md</code>（或同类版本更新说明）时。 核心：日志面向<strong>使用者</strong>，只回答「哪个组件、发生了什么、我要不要动代码」。 2026-10-26 对标主流组件库日志重构：借鉴「一条一现象」的条目粒度，新增 §1.2 长度上限、§4.1 条目顺序（<strong>不设分类小节</strong>，实测本项目多数版本 1–5 条，小节标题过重）、§4.2 冗余词、§4.3 issue 关联、§9 反模式清单。</p></blockquote><hr><h2 id="_1-描述方式-概括式" tabindex="-1">1. 描述方式：概括式 <a class="header-anchor" href="#_1-描述方式-概括式" aria-label="Permalink to &quot;1. 描述方式：概括式&quot;">​</a></h2><ul><li><strong>落笔前先过「读者决策测试」</strong>：这句能否改变读者的某个决定（要不要改代码 / 要不要覆盖某个变量 / 会不会踩到）？不能就删 —— 尤其警惕为满足 §3「必须写清」而补的括号：默认值未变、新功能的默认行为、取值关系（<code>取 A 的浅一档</code>、<code>按尺寸取 small 档</code>）一律不补</li><li><strong>一条一句话</strong>，只写「改了什么 + 影响」；根因、算法、实现手段不写进日志</li><li>「一句话」指<strong>概括方式</strong>（不展开根因与实现细节），不是「一句里塞多件事」</li><li>❌ <code>定位尺寸改用 offsetWidth / offsetHeight，因为 transform 会让 getBoundingClientRect 返回缩放后的视觉尺寸</code></li><li>✅ <code>修复缩放动画期间位置错位</code></li><li>表述落到<strong>结果层</strong>：需要读者理解内部机制才读懂的写法必须改写（❌ <code>坏键不再中断回调，其余组件主题色恢复更新</code> → ✅ <code>坏键改为忽略并告警</code>）</li><li><strong>不复述未变化的取值</strong>：默认值 / 默认行为没变时，不写「未传入时仍跟随 X（X + 24）」这类取值细节，只写「修复 X 属性不生效的问题」</li><li>根因、取舍与实现细节归 commit message / PR 描述</li><li><strong>边界</strong>：「实现细节」指内部构建 / 脚本 / 测试 / 重构等使用者不可感知的改动；<strong><code>docs/</code> 与 <code>development/</code> 的内容更新不属于此列，必须入日志</strong>（写法见 §2、§3）</li></ul><h3 id="_1-1-细节颗粒-留锚点-删症状" tabindex="-1">1.1 细节颗粒：留锚点，删症状 <a class="header-anchor" href="#_1-1-细节颗粒-留锚点-删症状" aria-label="Permalink to &quot;1.1 细节颗粒：留锚点，删症状&quot;">​</a></h3><ul><li><strong>必须保留检索锚点</strong>：属性 / 事件 / 方法 / 插槽 / <code>CSS</code> 变量名（如 <code>start()</code>、<code>interval</code>、<code>itemStyle</code>）——读者靠它们在自研代码里对号，删了就无法判断是否波及自己</li><li><strong>症状不复述</strong>：同一问题能观察到的多个症状不逐条列，最多留<strong>一句</strong>最有辨识度的 <ul><li>❌ <code>重复调用 start() 会叠加（越滚越快、stop() 停不下来），KeepAlive 失活后仍在推进、返回时已跳到其他条目，卸载后残留定时器</code></li><li>✅ <code>垂直滚动的启停：start() 重复调用与卸载后调用不再叠加滚动、KeepAlive 失活即暂停</code></li></ul></li><li>症状白描属「读者本就知道的表象」，锚点与影响属「读者尚未掌握的信息」，篇幅优先给后者</li></ul><h3 id="_1-2-长度上限-2026-10-26-新增" tabindex="-1">1.2 长度上限（2026-10-26 新增） <a class="header-anchor" href="#_1-2-长度上限-2026-10-26-新增" aria-label="Permalink to &quot;1.2 长度上限（2026-10-26 新增）&quot;">​</a></h3><ul><li><strong>单条 ≤ 120 字</strong>（不含 Markdown 链接与行内代码），超过先按 §2 判断能否合并，不能合并再按「读者是否要做不同动作」拆条</li><li>判据：一条里出现 <strong>≥3 个分号分句</strong>，通常说明装了多个主题，必须拆</li><li>一个版本块超过 15 条时，回头检查是否存在同主题可合并项（历史最长条目 670 字、单块 16 条，均属超载）</li></ul><h2 id="_2-合并同源、拆开异源" tabindex="-1">2. 合并同源、拆开异源 <a class="header-anchor" href="#_2-合并同源、拆开异源" aria-label="Permalink to &quot;2. 合并同源、拆开异源&quot;">​</a></h2><ul><li><strong>判定顺序：先合并，再拆分</strong> —— 同一组件、同一工具函数族、同一能力主题的多个改动<strong>默认合并为一条</strong>（主句概括 + 括号 / 分句承接具体结果）；仅当合并后一条里仍有<strong>不相关主题</strong>时，才拆开</li><li><strong>条目数 ≈ 主题数，不是症状数</strong>：同一组件的多个修复落在同一主题（滚动行为 / 表单校验 / 样式属性 / 主题变量…）就只写一条；<strong>补丁版本只动一个组件时，正常是 1 条（+ 兜底条）</strong></li><li>❌ 同组件拆两条：<code>修复 ConfigProvider 运行期增删组件键不生效</code> + <code>修复 ConfigProvider 对非本库组件键的处理</code>（读者要把同一个主语读两遍）</li><li>✅ <code>修复 [全局化配置 ConfigProvider](/guide/components/config-provider.html) 组件级主题：运行期增删组件键即时生效（新增覆盖生效、移除覆盖回退 common），theme 中的非本库组件键改为忽略并告警</code></li><li><strong>「不相关主题」的判定</strong>：读者是否需要<strong>做出不同动作 / 关注不同 API 面</strong>（如行为修复与破坏性 API 变更并存）——「行为 vs 样式」「代码 vs 文档」这类内部分类不算不相关，<strong>不得据此拆条</strong></li><li>❌ 一条里混入多个<strong>不相关主题</strong>（如「新增属性 + 构建产物调整」）—— 读者无法判断其中哪句与自己相关</li><li><strong>同一组件名 / 主题不应在相邻多条里重复出现</strong>，出现即说明该合并</li><li>合并的对象是「同源改动」，不是「为控制条数而压缩」；确实不同源就拆开，宁可条数多也不要堆叠</li><li><strong>同源文档更新并入该条</strong>（不另起「更新文档」条），但仍须按 §3 写明受众与主题</li><li>收尾条目（如「组件库及文档代码优化」）按维护者习惯保留，不擅自删除或改写 —— 但<strong>不是省略文档更新</strong>：文档更新须写明「<strong>哪类受众文档</strong>（使用者文档 <code>docs/</code> / <code>README</code>、贡献者文档 <code>development/</code> / <code>CONTRIBUTING</code>）+ <strong>变了什么主题</strong>」；<strong>不写具体文件路径</strong>，排版 / 格式类调整不展开细节（列数、格式名等）；受众不同的文档更新各自成条，禁止「优化文档」这类一句打包写法</li></ul><h2 id="_3-保留必要信息-不得过度概括" tabindex="-1">3. 保留必要信息（不得过度概括） <a class="header-anchor" href="#_3-保留必要信息-不得过度概括" aria-label="Permalink to &quot;3. 保留必要信息（不得过度概括）&quot;">​</a></h2><p>以下必须写清，压缩到看不出影响即不合格：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>破坏性变更</td><td><strong>不标注</strong>「破坏性变更」字样或用 <code>⚠️</code> 等强调标记，按动词正常起句，写明「移除了什么 / 改用什么」</td></tr><tr><td>默认值变化</td><td>写明旧值 → 新值（<strong>未变化时不复述默认值</strong>）</td></tr><tr><td>需用户改代码</td><td>写明替代写法</td></tr><tr><td>影响面 / 触发条件</td><td>写明「什么配置下会踩到」+「同参数下表现是否变化」：<code>interval</code> 改为纯停留时长后，同一取值整体滚动变慢，需调速的读者据此下调；<code>itemStyle</code> 的 <code>maxWidth</code> 仅开启 <code>ellipsis</code> 时失效，不能写成「垂直滚动时失效」</td></tr><tr><td>文档更新</td><td>按受众写「使用者文档 / 贡献者文档 / <code>README</code>」+ 变了什么主题；不写文件路径与排版细节，不写「优化文档」这类打包表述</td></tr><tr><td>与某修复同源的文档更新</td><td>并入该修复条（不另起条），仍写明受众 + 主题</td></tr></tbody></table><h2 id="_4-格式约定" tabindex="-1">4. 格式约定 <a class="header-anchor" href="#_4-格式约定" aria-label="Permalink to &quot;4. 格式约定&quot;">​</a></h2><ul><li>每条以动词开头：<code>新增</code> / <code>优化</code> / <code>增强</code> / <code>修复</code> / <code>重构</code></li><li><strong>不使用 <code>⚠️</code> 等强调标记</strong>：破坏性变更 / 默认值变化 / API 移除同样以动词正常起句，靠正文里的「原 X → 现 Y」说清影响，不加前缀、不加粗警示</li><li>组件与工具函数名用 Markdown 链接指向文档，如 <code>[文字提示 Tooltip](/guide/components/tooltip.html)</code></li><li>属性名、API、全局对象等用行内代码包裹</li><li><strong>条目数不设上限</strong>：由改动量自然决定 —— 架构重构、批量破坏性变更的大版本条目自然多，小版本自然少</li><li><strong>不为凑数拆分</strong>（一件事写成多条），<strong>也不为控数堆叠或删减信息</strong>（多件事挤进一条、砍掉必要语义）</li><li>每条长度以「一句话可读」为准：合并后的具体结果用括号 / 分句承接，可用分号把「启停 / 节奏 / 样式」等子话题分组</li><li><strong>「并列项 ≤ 2」只是排版建议</strong>（超了先概括或分组），<strong>不作拆条依据</strong>；是否拆条只按 §2 的主题判定</li></ul><h3 id="_4-1-条目顺序-2026-10-26-·-不设分类小节" tabindex="-1">4.1 条目顺序（2026-10-26 · 不设分类小节） <a class="header-anchor" href="#_4-1-条目顺序-2026-10-26-·-不设分类小节" aria-label="Permalink to &quot;4.1 条目顺序（2026-10-26 · 不设分类小节）&quot;">​</a></h3><ul><li><strong>不设 <code>###</code> 分类小节</strong>（变更 / 新增 / 修复…）：多数版本只有 1–5 条，小节标题比条目本身还重，视觉上与版本号同量级、打断阅读节奏；历史 2.x 版本一直是直排，混排反而更乱。</li><li>可扫描性靠两件事实现，不靠标题： <ol><li><strong>变更置顶</strong>：API 移除 / 更名、默认值变化、需改造的类名与变量，相关条目排在版本块最前（同组件的其余条目可紧随其后）</li><li><strong>动词起句</strong>：<code>新增</code> / <code>优化</code> / <code>修复</code> / <code>移除</code> / <code>改为</code> 一眼可辨类型；<code>⚠️</code> 与「破坏性变更」标记一律不写（见 §4）</li></ol></li><li>单版本 ≥10 条且跨 3 个以上组件主题时，可用行内粗体 <code>**变更**</code> 做视觉分组，<strong>仍不用 <code>###</code></strong>（避免撑爆页面目录）</li></ul><h3 id="_4-2-冗余词与模糊表述-2026-10-26-新增" tabindex="-1">4.2 冗余词与模糊表述（2026-10-26 新增） <a class="header-anchor" href="#_4-2-冗余词与模糊表述-2026-10-26-新增" aria-label="Permalink to &quot;4.2 冗余词与模糊表述（2026-10-26 新增）&quot;">​</a></h3><ul><li>组件链接后<strong>不加「组件」二字</strong>：<code>[按钮 Button](/guide/components/button.html)</code>，不写 <code>… 组件</code>（历史存量 302 处）</li><li><strong>禁止「优化并更新 X 组件」这类只报动作不报结果的句式</strong>（历史存量 249 条，占全部条目 41%）；必须写清改了什么、影响什么</li><li>不写「完善 / 相关代码 / 部分功能 / 优化调整」等无法定位对象的模糊表述</li><li>一条内不重复同一个组件链接；相邻条目用「上述 N 个组件」承接已合并的同主题改动</li></ul><h3 id="_4-3-issue-关联-2026-10-26-新增" tabindex="-1">4.3 issue 关联（2026-10-26 新增） <a class="header-anchor" href="#_4-3-issue-关联-2026-10-26-新增" aria-label="Permalink to &quot;4.3 issue 关联（2026-10-26 新增）&quot;">​</a></h3><ul><li>有对应 issue 时，条目末补 <code>，关闭 [#编号](https://github.com/themusecatcher/vue-amazing-ui/issues/编号)</code></li><li>只在确有对应 issue 时写；不写 PR 号、作者、评审信息</li></ul><h2 id="_5-版本与历史" tabindex="-1">5. 版本与历史 <a class="header-anchor" href="#_5-版本与历史" aria-label="Permalink to &quot;5. 版本与历史&quot;">​</a></h2><ul><li>已发布版本的历史条目<strong>默认不回改</strong>，用户明确要求时才回改</li><li>新版本严格按本规范撰写，不因历史风格而妥协</li><li>回改历史条目只做四件事：删实现细节（见 §6）、去掉 <code>⚠️</code> /「破坏性变更」标记并改为动词起句、按 §2 合并同主题条目、按 §4.1 把 API 变更条目置顶；<strong>兜底条目原样保留</strong>（见 §6 末条）</li><li>版本块<strong>至少 1 条</strong>：只写标题、没有条目的空版本块等于「发了个什么都没说的版本」，发布前必须补齐（<code>3.3.2</code> 曾出现空块）</li><li><strong>2026-10-26 已完成一次全量存量回改</strong>（170 个版本、616 条 → 564 条）：统一动词（去掉「优化并更新」249 处）、删「… 组件」后缀（300 余处）、修中文标点前空格（232 行）、合并同主题批量条目（如 <code>2.2.12</code> 的 22 条主题色改造并为 5 条）、零信息条目统一为「优化 X 的组件实现」、修正 5 处指向错误组件的链接；此后按本规范写新版本，历史不再重复回改</li><li>回改不改写事实、不合并版本、不动 <code>VersionDateTag</code>、链接与版本号；改完自查「版本数不变、无空版本块」</li></ul><h2 id="_6-实现细节一律不写" tabindex="-1">6. 实现细节一律不写 <a class="header-anchor" href="#_6-实现细节一律不写" aria-label="Permalink to &quot;6. 实现细节一律不写&quot;">​</a></h2><p>日志只保留「组件 / 能力 + 可感知结果」，以下内容属于实现细节，出现即删：</p><table tabindex="0"><thead><tr><th>类别</th><th>❌ 不写</th><th>✅ 只写结果</th></tr></thead><tbody><tr><td>常量数值</td><td><code>动效时长由 0.3s 收敛为 0.2s</code>、<code>基线压低 1px</code>、<code>默认色 15% 黑</code></td><td><code>动效时长缩短</code>、<code>基线压低</code>、<code>默认色随模式反转</code></td></tr><tr><td>缓动 / 曲线 / 关键帧</td><td><code>两段同为 ease-out-circ</code>、<code>进场与离场各用一条缓动曲线</code></td><td>不写（除非本身就是可配置的 API）</td></tr><tr><td>内部 API 与算法</td><td><code>requestAnimationFrame 合并同帧重算</code>、<code>按 placement 分组管理数据与定时器</code>、<code>模块级统一捕获点击位置</code></td><td>只写用户看到的变化</td></tr><tr><td>取值关系 / 派生链</td><td><code>内环取外环色的浅一档</code>、<code>按遮罩尺寸取 small 档</code>、<code>底色取主色派生的暗调</code>、<code>文字色改取容器底色</code></td><td><code>内环跟随外环取色</code>、<code>字号随遮罩尺寸变化</code>、<code>底色跟随主题色</code>，不写值从哪来</td></tr><tr><td>内部术语</td><td><code>并存两条滚动节拍</code>、<code>与 Swiper 的 interval 口径一致</code></td><td>换成使用者视角：<code>越滚越快、stop() 停不下来</code>、不写对标</td></tr><tr><td>构造与结构</td><td><code>svg 改为声明式渲染</code>、<code>不再在 setup 阶段访问全局对象</code>、<code>改用交互式演示</code></td><td><code>体积减小</code>、<code>修复 SSR 渲染报错</code>、<code>补充可运行示例</code></td></tr><tr><td>依赖与构建</td><td><code>移除 @vuepic/vue-datepicker</code>、<code>新增第三方样式单一数据源</code>、<code>优化 vite 构建配置</code></td><td><code>移除第三方依赖</code>；纯构建 / 脚本 / 测试改动不进日志</td></tr></tbody></table><ul><li><strong>删除优于模糊化</strong>：拿不准怎么概括就整句删掉，不要换成「优化了性能 / 调整了逻辑」这类更空的表述</li><li><strong>例外</strong>：常量本身就是公开 API（属性默认值、枚举取值、<code>CSS</code> 变量名）时按 §3 写清旧值 → 新值</li><li><strong>兜底条目不在回改范围</strong>：<code>组件库及文档代码优化</code>、<code>优化 X 组件代码 / 组件实现</code>、<code>组件库脚本优化</code> 等是作者刻意保留的版本记录 —— §2 的「兜底条目不写」只约束新版本，历史条目里已有的原样保留</li></ul><h2 id="_7-事实核实" tabindex="-1">7. 事实核实 <a class="header-anchor" href="#_7-事实核实" aria-label="Permalink to &quot;7. 事实核实&quot;">​</a></h2><ul><li>日志里出现的<strong>组件名 / 属性名 / 事件名 / 文档链接</strong>必须在源码或 <code>docs/</code> 里核实存在，不靠印象</li><li><strong>跨组件对标</strong>只在两边 API 名真正对得上时才写：❌ <code>与 [轮播图 Swiper] 的 interval 口径一致</code>（Swiper 实为 <code>delay</code> / <code>speed</code>）→ ✅ 只写「停留与过渡分开计时」，不写对标</li><li>默认值、旧值 → 新值回源码确认（<code>Props</code> 接口 / <code>withDefaults</code> / 组件 <code>docs</code> 属性表），不凭记忆写数字或属性名</li><li>修复类条目落笔前先回看 diff，确认「修的范围」与「写的范围」一致（如仅某分支失效，不得写成整体失效）</li></ul><h2 id="_8-自检清单" tabindex="-1">8. 自检清单 <a class="header-anchor" href="#_8-自检清单" aria-label="Permalink to &quot;8. 自检清单&quot;">​</a></h2><ul><li>[ ] <strong>读者决策测试</strong>：每条能否改变读者的某个决定？不能则删；括号里的补充是否属于「默认值未变 / 新功能默认行为 / 取值关系」？</li><li>[ ] 是否残留<strong>取值关系 / 派生链 / 机制动词</strong>（派生、承接、跟随取色、转深、叠压、按…计算）？</li><li>[ ] 每条能否一句话说清「改了什么 + 影响」？</li><li>[ ] 同组件 / 同工具函数族 / 同能力主题的改动是否已<strong>优先合并</strong>为一条？（先合并，再拆分）</li><li>[ ] <strong>条目数是按「主题数」还是「症状数」定的</strong>？同组件的同类修复是否还在分条？（单组件补丁版本通常 1 条）</li><li>[ ] 同一组件名 / 主题是否在相邻多条里重复出现？出现即合并</li><li>[ ] 是否存在「一条堆叠多个不相关主题」的情况？应拆为多条</li><li>[ ] 是否残留<strong>症状白描</strong>？该留的 API / 属性锚点是否齐全？</li><li>[ ] 破坏性变更、默认值变化是否写明替代用法？未变化的默认值是否已删去复述？</li><li>[ ] 是否写明<strong>触发条件</strong>与对既有取值的影响（同参数下表现是否变化）？</li><li>[ ] 是否残留 <code>⚠️</code> 或「破坏性变更」前缀等强调标记？（一律不写）</li><li>[ ] 是否残留根因、算法、内部函数名、内部术语，或需要读者理解内部机制才读懂的表述？</li><li>[ ] 是否残留具体常量数值（时长 / 像素 / 百分比）、缓动曲线、内部 API 或构建手段？（见 §6）</li><li>[ ] <strong>引用的组件 / 属性 / 链接是否核实存在</strong>？跨组件对标的两边 API 名对得上吗？</li><li>[ ] 回改历史时是否只删实现细节（兜底条目原样保留）、版本数与版本块结构未受损？</li><li>[ ] 文档更新是否按受众写明「哪类文档 + 变了什么主题」？（不写文件路径与排版细节；同源更新已并入该条；合并 / 拆条沿用项目既有风格）</li><li>[ ] 是否擅自删掉了维护者惯用的收尾条目（如「组件库及文档代码优化」）？应原样保留</li><li>[ ] 是否为了控制条数而删减或模糊了必要信息？（条目数不是压缩目标）</li><li>[ ] API 变更 / 默认值变化条目是否排在版本块最前（§4.1）？是否误用了 <code>###</code> 分类小节？</li><li>[ ] 单条是否 ≤120 字（不含链接）？是否残留 ≥3 个分号分句的超载条目？</li><li>[ ] 是否残留「… 组件」后缀与「优化并更新 X 组件」句式？</li><li>[ ] 版本块是否至少 1 条、<code>date</code> 是否非未来日期？</li><li>[ ] 有对应 issue 的是否已补 <code>，关闭 #编号</code>？</li></ul><h2 id="_9-反模式清单-2026-10-26-全量盘点" tabindex="-1">9. 反模式清单（2026-10-26 全量盘点） <a class="header-anchor" href="#_9-反模式清单-2026-10-26-全量盘点" aria-label="Permalink to &quot;9. 反模式清单（2026-10-26 全量盘点）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>反模式</th><th>正确做法</th></tr></thead><tbody><tr><td>版本块只有标题、没有条目</td><td>发布前至少 1 条，兜底条不可省</td></tr><tr><td>版本日期写成未来日期</td><td>预写取当天；发布当天如非同日须更新</td></tr><tr><td>一条塞 5–8 件事（历史最长 670 字）</td><td>按 §1.2 拆分，或按 §2 换成多条同主题条目</td></tr><tr><td>同主题拆多条（4 条都写「暗色下不可见」）</td><td>按 §2 先合并为一条并列式</td></tr><tr><td>同组件跨主题硬塞一条</td><td>按「读者是否要做不同动作」拆开</td></tr><tr><td>「优化并更新 X 组件」只报动作</td><td>写清改了什么、影响什么</td></tr><tr><td>组件链接后带「组件」二字</td><td>删后缀（历史存量 302 处）</td></tr><tr><td>文档更新一句打包「优化文档」</td><td>写明受众（使用者文档 / 贡献者文档 / <code>README</code>）+ 主题</td></tr><tr><td>缺省值复述、常量数值、缓动曲线、内部 API</td><td>按 §6 删除；仅公开 API 的默认值写旧值 → 新值</td></tr><tr><td>API 移除 / 默认值变化混在功能条目里排到最后</td><td>置顶（§4.1）</td></tr><tr><td>用 <code>###</code> 小节切分只有 1–5 条的版本块</td><td>直排，靠动词与置顶识别</td></tr><tr><td>用 <code>⚠️</code> /「破坏性变更」前缀强调</td><td>删标记，动词正常起句</td></tr><tr><td>发布版本与 <code>package.json</code> version 不一致</td><td>双处同步后对照校验</td></tr></tbody></table>',35)])])}const _=o(r,[["render",i]]);export{u as __pageData,_ as default};
